#!/usr/bin/env bash
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
out="${1:-$here/../../../target/guests/processes}"
mkdir -p "$out"
musl-gcc -static -pthread -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/process" "$here/process.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/pty" "$here/pty.c"
musl-gcc -static -pthread -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/signalfd" "$here/signalfd.c"
musl-gcc -static -pthread -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/mqueue" "$here/mqueue.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/timer-waits" "$here/timer-waits.c"
musl-gcc -static -pthread -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/keys" "$here/keys.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/inotify" "$here/inotify.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/fanotify" "$here/fanotify.c"
musl-gcc -static -pthread -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/userfaultfd" "$here/userfaultfd.c"
musl-gcc -static -pthread -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/aio" "$here/aio.c"
# A build ID of its own for perf-side-band's MMAP2 records, which musl-gcc's
# link spec may leave out.
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -Wl,--build-id=sha1 -o "$out/perf" "$here/perf.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/bpf" "$here/bpf.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/bpf-prog" "$here/bpf-prog.c"
musl-gcc -static -pthread -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/ptrace" "$here/ptrace.c"
musl-gcc -static -pthread -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/ptrace-syscalls" "$here/ptrace-syscalls.c"
musl-gcc -static -pthread -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/ptrace-requests" "$here/ptrace-requests.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/single-step" "$here/single-step.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/netlink-options" "$here/netlink-options.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth" "$here/veth.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv4" "$here/veth-ipv4.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-traffic" "$here/veth-traffic.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-iif" "$here/veth-iif.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-broadcast" "$here/veth-broadcast.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-filter" "$here/veth-filter.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-broadcast-source" "$here/veth-broadcast-source.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/mapped-source" "$here/mapped-source.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/udp-disconnect" "$here/udp-disconnect.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-neigh" "$here/veth-neigh.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv6" "$here/veth-ipv6.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv4-gateway" "$here/veth-ipv4-gateway.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv4-ecmp" "$here/veth-ipv4-ecmp.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv4-hash" "$here/veth-ipv4-hash.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-answers" "$here/veth-answers.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv4-via" "$here/veth-ipv4-via.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv6-source" "$here/veth-ipv6-source.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv6-gateway" "$here/veth-ipv6-gateway.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv6-ecmp" "$here/veth-ipv6-ecmp.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-bindtodevice" "$here/veth-bindtodevice.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-multicast" "$here/veth-multicast.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/inet-diag-device" "$here/inet-diag-device.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv6-multicast" "$here/veth-ipv6-multicast.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv6-accept" "$here/veth-ipv6-accept.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv6-oif" "$here/veth-ipv6-oif.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv6-scope" "$here/veth-ipv6-scope.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/veth-ipv6-traffic" "$here/veth-ipv6-traffic.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/proc-net" "$here/proc-net.c"
musl-gcc -static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/x87" "$here/x87.c" -lm
# The same on musl's dynamic linker by a name exec finds in the working
# directory, where inotify-interpreter puts a copy of it.
musl-gcc -O1 -fno-stack-protector -fcf-protection=none -pie -fPIE -Wl,--dynamic-linker=inotify-ld.so -o "$out/inotify-interp" "$here/inotify.c"
# The dynamic case: its linker is the one musl-gcc names, on the host and in the
# emulator.
musl-gcc -shared -fPIC -O1 -fno-stack-protector -o "$out/dynamic-plugin.so" "$here/dynamic-plugin.c"
musl-gcc -pthread -O1 -fno-stack-protector -fcf-protection=none -pie -fPIE -o "$out/dynamic" "$here/dynamic.c"
musl-gcc -pthread -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie -o "$out/dynamic-no-pie" "$here/dynamic.c"
# And on glibc's, which is the host's.
gcc -shared -fPIC -O1 -fno-stack-protector -o "$out/dynamic-glibc-plugin.so" "$here/dynamic-plugin.c"
gcc -pthread -O1 -fno-stack-protector -fcf-protection=none -pie -fPIE -DPLUGIN_NAME='"dynamic-glibc-plugin.so"' -o "$out/dynamic-glibc" "$here/dynamic.c" -ldl
rustc --target x86_64-unknown-linux-musl -C opt-level=1 -C target-feature=+crt-static -o "$out/command" "$here/command.rs"
